import{_ as a,p as e,q as n,Y as s}from"./framework-e1bed10d.js";const t={},c=s(`<h1 id="异常" tabindex="-1"><a class="header-anchor" href="#异常" aria-hidden="true">#</a> 异常</h1><p>代码的编写出现非正常现象，称为异常，异常分为编译时异常和运行时异常，编译时异常必须处理，运行时异常可以不处理，但是建议处理 异常都是一个一个的类型，继承自Throwable类，除了RuntimeException及其子类，其他都是编译时异常</p><p>异常处理常用的两种方式：try-catch和throws</p><h2 id="常用api" tabindex="-1"><a class="header-anchor" href="#常用api" aria-hidden="true">#</a> 常用api</h2><h3 id="构造方法" tabindex="-1"><a class="header-anchor" href="#构造方法" aria-hidden="true">#</a> 构造方法</h3><ul><li>Exception()：用null构造一个新异常，调用initCause(Throwable case)进行初始化</li><li>Exception(String message)：用指定的详细消息构造一个新异常。</li><li>Exception(String message, Throwable cause)：用指定的详细消息和原因构造一个新异常。</li><li>protected Exception(String message, Throwable cause, boolean enableSuppression, boolean writableStackTrace)：用指定的详细消息、原因、启用或禁用抑制以及启用或禁用可写堆栈跟踪构造一个新异常</li></ul><h3 id="实例方法" tabindex="-1"><a class="header-anchor" href="#实例方法" aria-hidden="true">#</a> 实例方法</h3><ul><li>Throwable getCause()：返回此throwable的原因，如果原因不存在或未知，则返回null</li><li>String getMessage()：返回此throwable的详细消息字符串</li><li>StackTraceElement[] getStackTrace()：提供对由printStackTrace()打印的堆栈跟踪信息的编程访问</li><li>Throwable initCause(Throwable cause)：将此throwable的cause初始化为指定值</li><li>void printStackTrace()：将此throwable及其回溯打印到标准错误流</li><li>void setStackTrace(StackTraceElement[] stackTrace)：设置将由getStackTrace()返回并由printStackTrace()及相关方法打印的堆栈跟踪元素</li></ul><h2 id="try-catch" tabindex="-1"><a class="header-anchor" href="#try-catch" aria-hidden="true">#</a> try-catch</h2><p>try-catch使用代码块包括语句，可以使用多个catch处理不同的异常类型，语法格式如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token comment">// 代码块1</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span><span class="token punctuation">(</span>exceptionType1 e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 代码块2</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span><span class="token punctuation">(</span>exceptionType2 e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 代码块3</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 try 语句块中发生异常，那么一个相应的异常对象就会被拋出，然后 catch 语句就会依据所拋出异常对象的类型进行捕获并处理。处理之后，程序会跳过 try 语句块中剩余的语句，转到 catch 语句块内部的第一条语句开始执行</p><p>如果 try 语句块中没有异常发生，那么 try 块正常结束，后面的 catch 语句块被跳过，程序将从 catch 语句块后的第一条语句开始执行</p><p>catch处理异常，可以使用以下三种方式对异常信息进行输出</p><ul><li>e.printStackTrace()：指出异常的类型、性质、栈层次及出现在程序中的位置</li><li>e.getMessage()：返回异常的性质</li><li>e.toString()：返回异常的性质和类型</li></ul><p>finally用于指定无论try和catch中的代码是否执行完，都会执行的代码</p><h2 id="throws" tabindex="-1"><a class="header-anchor" href="#throws" aria-hidden="true">#</a> throws</h2><p>throws用于指定方法中可能发生的异常，编译器检查方法调用时是否处理了异常，如果处理了，则编译通过；如果未处理，则编译不通过</p><p>一般用于在该方法中不处理异常，交给方法的调用者</p><p>格式如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code>returnType <span class="token function">methodName</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> 异常类<span class="token number">1</span><span class="token punctuation">,</span>异常类<span class="token number">2</span><span class="token punctuation">,</span>异常类<span class="token number">3</span><span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,21),i=[c];function l(r,p){return e(),n("div",null,i)}const u=a(t,[["render",l],["__file","exception.html.vue"]]);export{u as default};
